-- backfill_chunks.sql
DECLARE
  CURSOR c_chunks IS
    SELECT DBMS_ROWID.ROWID_CREATE(1, data_object_id, relative_fno, block_id, 0)
             AS start_rowid,
           DBMS_ROWID.ROWID_CREATE(1, data_object_id, relative_fno,
                                   block_id + blocks - 1, 32767) AS end_rowid
    FROM dba_extents
    WHERE segment_name = 'TARGET_TABLE' AND owner = 'SCHEMA'
    ORDER BY block_id;
BEGIN
  FOR chunk IN c_chunks LOOP
    UPDATE target_table SET new_col = compute_value(old_col)
    WHERE ROWID BETWEEN chunk.start_rowid AND chunk.end_rowid;
    COMMIT;
    DBMS_LOCK.SLEEP(0.1);
  END LOOP;
END;
